const data = $json;

// Validation des données reçues
if (!data.name && !data.company) {
  return [{json: {error: 'name ou company requis', success: false}}];
}

const prompt = `Tu es un expert en qualification de prospects B2B Salesforce.

Analyse ce prospect et enrichis ses données:
- Nom: ${data.name || 'N/A'}
- Titre: ${data.title || 'N/A'}
- Entreprise: ${data.company || 'N/A'}
- LinkedIn URL: ${data.linkedin_url || 'N/A'}
- Email: ${data.email || 'N/A'}

Détermine:
1. Si c'est un décideur potentiel pour Salesforce (score 1-10)
2. Les pain points probables de son entreprise
3. Le meilleur angle d'approche
4. La taille probable de l'entreprise

Réponds en JSON:
{"decision_maker_score": X, "company_size": "...", "pain_points": ["..."], "approach_angle": "...", "industry": "..."}`;

return [{json: {...data, prompt}}];

const original = $("Prepare Analysis").first().json;
const r = $json.response || '';

let enrichment = {
  decision_maker_score: 5,
  company_size: 'unknown',
  pain_points: [],
  approach_angle: '',
  industry: 'unknown'
};

try {
  const jsonMatch = r.match(/\{[\s\S]*decision_maker_score[\s\S]*\}/);
  if (jsonMatch) {
    enrichment = {...enrichment, ...JSON.parse(jsonMatch[0])};
  }
} catch(e) {}

return [{json: {
  success: true,
  original: {
    name: original.name,
    title: original.title,
    company: original.company,
    email: original.email,
    linkedin_url: original.linkedin_url
  },
  enrichment
}}];
